package io.github.hienpham0344.stayfinder.support;
import io.github.hienpham0344.stayfinder.support.service.*;import io.github.hienpham0344.stayfinder.support.repository.*;import io.github.hienpham0344.stayfinder.support.dto.*;import io.github.hienpham0344.stayfinder.booking.repository.BookingRepository;import io.github.hienpham0344.stayfinder.common.idempotency.IdempotencyService;import io.github.hienpham0344.stayfinder.common.exception.*;
import org.junit.jupiter.api.Test;import java.util.*;import java.time.*;import java.util.function.Supplier;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class SupportReportTest{
 @Test void createsServerIdSubmittedStatusWithoutExternalPromise(){var rows=mock(SupportReportRepository.class);var idem=mock(IdempotencyService.class);when(idem.execute(any(),anyString(),anyString(),any(),any(),any())).thenAnswer(i->((Supplier<?>)i.getArgument(5)).get());when(rows.save(any())).thenAnswer(i->i.getArgument(0));var now=Instant.parse("2026-10-13T12:00:00Z");var service=new SupportReportService(rows,mock(BookingRepository.class),idem,Clock.fixed(now,ZoneOffset.UTC));var result=service.submit(UUID.randomUUID(),new SupportReportRequest("Other"," Synthetic report ",null),"report-key");assertNotNull(result.reportId());assertEquals("submitted",result.status());assertEquals(now,result.createdAt());assertEquals(3,result.getClass().getRecordComponents().length);}
 @Test void validatesTextCategoryAndOptionalBookingOwnership(){var rows=mock(SupportReportRepository.class);var bookings=mock(BookingRepository.class);var service=new SupportReportService(rows,bookings,mock(IdempotencyService.class),Clock.systemUTC());var owner=UUID.randomUUID();for(var request:List.of(new SupportReportRequest("Unknown","text",null),new SupportReportRequest("Other"," ",null),new SupportReportRequest("Other","x".repeat(5001),null)))assertThrows(BusinessException.class,()->service.submit(owner,request,"report-key"));assertEquals(ErrorCode.BOOKING_NOT_FOUND,assertThrows(BusinessException.class,()->service.submit(owner,new SupportReportRequest("Booking","text",UUID.randomUUID()),"report-key")).getErrorCode());verify(rows,never()).save(any());}
}
